Aplikasi **Todo** sederhana:

```html
<!doctype html>
<html lang="id"><head>
<meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>Todo</title>
<style>
body{margin:0;background:#0b1220;color:#e8f1ff;font:16px system-ui;display:grid;place-items:center;min-height:100vh}
.box{width:min(420px,92vw);background:#132033;padding:1.25rem;border-radius:1rem}
input,button{padding:.6rem .8rem;border-radius:.5rem;border:0}
input{width:70%}button{background:#5eb0ff;font-weight:600}
ul{list-style:none;padding:0}li{padding:.5rem0;border-bottom:1px solid #1e2f48;display:flex;justify-content:space-between}
</style></head><body>
<div class="box">
<h1>Todo</h1>
<form id="f"><input id="i" placeholder="Tugas baru"/><button>Tambah</button></form>
<ul id="l"></ul>
</div>
<script>
const l=document.getElementById('l'),i=document.getElementById('i');
document.getElementById('f').onsubmit=e=>{e.preventDefault();if(!i.value.trim())return;
const li=document.createElement('li');li.innerHTML=`<span>${i.value}</span>`;
const b=document.createElement('button');b.textContent='×';b.onclick=()=>li.remove();
li.append(b);l.append(li);i.value='';};
</script></body></html>
```
